   132→public(package) fun support_asset<CoinType>(registry: &mut EModeGroupRegistry, group: u8, params: NewEMode, ctx: &mut TxContext) {
   133→    assert!(registry.groups.contains(group), error::emode_group_not_exists());
   134→
   135→    let group = registry.groups.borrow_mut(group);
   136→    assert!(!group.assets.supports<EMode, CoinType>(), error::emode_group_already_supports_asset());
   137→
   138→    let mut emode = EMode { id: object::new(ctx) };
   139→
