   296→    let collateral: &mut EModeCollateral = dynamic_field::borrow_mut(&mut emode.id, DFKey<EModeCollateral> {});
   297→    collateral.collateral_factor = collateral_factor;
   298→    collateral.liquidation_factor = liquidation_factor;
   299→    collateral.liquidation_incentive = liquidation_incentive;
   300→
   301→    let borrow: &mut EModeBorrow = dynamic_field::borrow_mut(&mut emode.id, DFKey<EModeBorrow> {});
