   334→
   335→public fun list_assets(registry: &EModeGroupRegistry, group: u8, now: u64): vector<EModeInfo> {
   336→    registry.ensure_group_exists(group);
   337→
   338→    let group = registry.groups.borrow(group);
   339→
   340→    let oracle_base_token = group.get_oracle_base_token();
   341→    let assets = group.assets.keys();
   342→
   343→    let (mut i, n) = (0, assets.length());
   344→
   345→    let mut results = vector::empty<EModeInfo>();
   346→    while (i < n) {
   347→        let emode = group.assets.load_by_type(*assets.borrow(i));
   348→        let (deposit_limiter, borrow_limiter) = emode.limiter_usage(now);
   349→
   350→        results.push_back(
   351→            EModeInfo {
   352→                asset: *assets.borrow(i),
   353→                oracle_base_token,
   354→                collateral_factor: emode.collateral().collateral_factor(),
   355→                liquidation_factor: emode.collateral().liquidation_factor(),
   356→                liquidation_incentive: emode.collateral().liquidation_incentive(),
   357→                max_borrow_amount: emode.borrow().max_borrow_amount(),
   358→                borrow_weight: emode.borrow().borrow_weight(),
   359→                flash_loan_fee_rate: emode.flash_loan().fee_rate(),
   360→                deposit_limiter,
   361→                borrow_limiter,
   362→            }
   363→        );
   364→        i = i + 1;
   365→    };
   366→
   367→    results
   368→}
