   541→    assert!(!flashloan_a.fee_rate().eq(flashloan_b.fee_rate()), 21);
   542→
   543→    // Verify TestCoinA is NOT in group2 and TestCoinB is NOT in group1
   544→    assert!(!registry.is_support(group2, type_name_a), 22);
   545→    assert!(!registry.is_support(group1, type_name_b), 23);
   546→
   547→    scenario.end();
   548→    std::unit_test::destroy(registry);
   549→}
