   858→fun refresh_obligation_assets_interest<MarketType>(
   859→    assets: &GenericCoinTypeStorage<Asset<MarketType>>,
   860→    emode_group: &EModeGroup,
   861→    reserves: &mut GenericCoinTypeStorage<Reserve<MarketType>>,
   862→    obligation: &mut Obligation<MarketType>,
   863→    now: u64,
   864→) {
   865→    refresh_obligation_borrow_interest<MarketType>(assets, reserves, obligation, now);
   866→
   867→    // collateral
   868→    let asset_types = obligation.deposit_types();
   869→
   870→    let (mut i, n) = (0, asset_types.length());
   871→
   872→    while (i < n) {
